// runEnable sets the enabled flag in settings.
// Writes to the target file (local by default, project with --project),
// and also updates the other file if it exists, so they can't get out of sync.
func runEnable(ctx context.Context, w io.Writer, useProjectSettings bool) error {
	s, err := LoadEntireSettings(ctx)
	if err != nil {
		return fmt.Errorf("failed to load settings: %w", err)
	}

	s.Enabled = true

	if err := saveEnabledState(ctx, s, useProjectSettings); err != nil {
		return err
	}

	fmt.Fprintln(w, "Entire is now enabled.")
	printEnabledStatus(ctx, w)

	if s.UsesCustomMetadataRef() {
		if err := installMetadataRefspec(ctx); err != nil {
			fmt.Fprintf(w, "Warning: failed to install fetch refspec for %s: %v\n", paths.MetadataRefName, err)
		}
	}
	return nil
}

// installMetadataRefspec appends a fetch refspec on origin so subsequent
// `git fetch` calls pull refs/entire/checkpoints/v1 into the non-clobbering
// remote-tracking ref. Idempotent. No-op when origin is absent or the
// refspec is already present.
func installMetadataRefspec(ctx context.Context) error {
	if _, err := gitremote.GetRemoteURL(ctx, "origin"); err != nil {
		return nil //nolint:nilerr // no origin configured is not an error for this idempotent helper
	}
	refspec := "+" + paths.MetadataRefName + ":" + paths.MetadataTrackingRefName
	out, _ := exec.CommandContext(ctx, "git", "config", "--get-all", "remote.origin.fetch").Output() //nolint:errcheck // missing config key is normal; treated as "no refspec set yet"
	for _, line := range strings.Split(string(out), "\n") {
		if strings.TrimSpace(line) == refspec {
			return nil
		}
	}
	if err := exec.CommandContext(ctx, "git", "config", "--add", "remote.origin.fetch", refspec).Run(); err != nil {
		return fmt.Errorf("git config --add remote.origin.fetch %s: %w", refspec, err)
	}
	return nil
}

func runDisable(ctx context.Context, w io.Writer, useProjectSettings bool) error {
	s, err := LoadEntireSettings(ctx)
	if err != nil {
		return fmt.Errorf("failed to load settings: %w", err)
	}

	s.Enabled = false

	if err := saveEnabledState(ctx, s, useProjectSettings); err != nil {
		return err
	}

	fmt.Fprintln(w, "Entire is now disabled.")
	return nil
}

// saveEnabledState writes settings to the target file and also updates the
// other settings file if it exists, preventing local/project from getting
// out of sync on the enabled field.
func saveEnabledState(ctx context.Context, s *EntireSettings, useProjectSettings bool) error {
	if useProjectSettings {
		if err := SaveEntireSettings(ctx, s); err != nil {
			return fmt.Errorf("failed to save settings: %w", err)
		}
		// Also update local if it exists, so it doesn't override
		if localExists(ctx) {
			if err := SaveEntireSettingsLocal(ctx, s); err != nil {
				return fmt.Errorf("failed to save local settings: %w", err)
			}
		}
	} else {
		if err := SaveEntireSettingsLocal(ctx, s); err != nil {
			return fmt.Errorf("failed to save local settings: %w", err)
		}
	}
	return nil
}

